        sta flash_timer
update_crash_timer
        dec crash_timer
        beq update_crash_end
        rts
update_crash_end
        jmp rank_after_crash
; Runs in each main loop pass when $4089 = 1 (mission done): counts down $4072 to $96 and then goes to rank_after_mission.
update_mission_end
